package com.tencent.weknora.security;
import com.fasterxml.jackson.databind.*;
import java.nio.file.*;import java.time.*;import java.util.*;import javax.sql.DataSource;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.io.FileSystemResource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.init.ScriptUtils;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"weknora.jwt-secret=isolated-native-guard-http-secret","weknora.bridge.enabled=false","logging.level.root=WARN","debug=false","FRONTEND_BASE_URL=https://frontend.example///"})
@AutoConfigureMockMvc @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class KnowledgeBaseOwnershipHttpIntegrationTest {
    private static final Path DATABASE;static{try{DATABASE=Files.createTempFile("weknora-native-guard-http-",".db");DATABASE.toFile().deleteOnExit();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
    @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:sqlite:"+DATABASE+"?busy_timeout=10000");p.add("spring.datasource.driver-class-name",()->"org.sqlite.JDBC");}
    @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired DataSource datasource;@Autowired JwtCodec jwt;@Autowired AuthRepository repository;@Autowired ObjectMapper json;
    private String owner,invitee,other;
    @BeforeAll void schema()throws Exception{try(var c=datasource.getConnection()){for(String script:List.of("000000_init.up.sql","000005_messages_attachments_and_invitation_fields.up.sql","000007_system_admin_and_settings.up.sql","000003_knowledge_base_auto_tag_config.up.sql","000021_knowledge_profiles.up.sql"))ScriptUtils.executeSqlScript(c,new FileSystemResource("../migrations/sqlite/"+script));}}
    @BeforeEach void reset(){for(String table:List.of("kb_shares","organization_tenant_members","organizations","knowledge_bases","tenant_invitations","audit_logs","auth_tokens","tenant_api_keys","tenant_members","users","tenants","system_settings"))jdbc.update("DELETE FROM "+table);jdbc.update("INSERT INTO tenants(id,name,business) VALUES(7,'Workspace','test'),(8,'Other','test')");jdbc.update("INSERT INTO users(id,username,email,password_hash,tenant_id) VALUES('owner','Owner','owner@example.com','unused',7),('invitee','Invitee','invitee@example.com','unused',NULL),('other','Other','other@example.com','unused',NULL)");jdbc.update("INSERT INTO tenant_members(user_id,tenant_id,role,status) VALUES('owner',7,'owner','active')");owner=token("owner",7);invitee=token("invitee",0);other=token("other",0);}

    @Test void viewerCreatorCanUpdateOwnKnowledgeBase()throws Exception{kb("owner",7);role("viewer");mvc.perform(put("/api/v1/knowledge-bases/kb").header("Authorization","Bearer "+owner).contentType("application/json").content("{\"name\":\"Renamed\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.name").value("Renamed"));assertEquals("Renamed",jdbc.queryForObject("SELECT name FROM knowledge_bases WHERE id='kb'",String.class));}
    @Test void nonCreatorDenialBeforeMalformedJsonUsesOwnershipAudit()throws Exception{kb("other",7);role("contributor");for(int i=0;i<2;i++)mvc.perform(put("/api/v1/knowledge-bases/kb").header("Authorization","Bearer "+owner).contentType("application/json").content("{")).andExpect(status().isForbidden()).andExpect(jsonPath("$.error").value("Forbidden: must own the resource or have the required role"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_logs",Integer.class));assertEquals("/api/v1/knowledge-bases/:id",jdbc.queryForObject("SELECT request_path FROM audit_logs",String.class));assertEquals("KB",jdbc.queryForObject("SELECT name FROM knowledge_bases",String.class));}
    @Test void missingKnowledgeBasePrecedesMalformedJson()throws Exception{role("viewer");mvc.perform(put("/api/v1/knowledge-bases/missing").header("Authorization","Bearer "+owner).contentType("application/json").content("{")).andExpect(status().isNotFound()).andExpect(jsonPath("$.error.message").value("knowledge base not found"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM audit_logs",Integer.class));}
    @Test void sharedEditorWritesOwnerTenantAndRetainsCallerActor()throws Exception{kb("other",8);share("editor","editor");role("contributor");mvc.perform(put("/api/v1/knowledge-bases/kb").header("Authorization","Bearer "+owner).contentType("application/json").content("{\"name\":\"Shared change\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.tenant_id").value(8));assertEquals("Shared change",jdbc.queryForObject("SELECT name FROM knowledge_bases WHERE tenant_id=8",String.class));assertEquals(8L,jdbc.queryForObject("SELECT tenant_id FROM audit_logs WHERE action='kb.updated'",Long.class));assertEquals("owner",jdbc.queryForObject("SELECT actor_user_id FROM audit_logs WHERE action='kb.updated'",String.class));assertEquals("contributor",jdbc.queryForObject("SELECT actor_role FROM audit_logs WHERE action='kb.updated'",String.class));}
    @Test void tenantViewerSharedWriteDeniedBeforeMalformedBodyWithoutOwnershipAudit()throws Exception{kb("other",8);share("admin","admin");role("viewer");mvc.perform(put("/api/v1/knowledge-bases/kb").header("Authorization","Bearer "+owner).contentType("application/json").content("{")).andExpect(status().isForbidden()).andExpect(jsonPath("$.error.message").value("Permission denied to access this knowledge base"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM audit_logs",Integer.class));}
    @Test void sourceDepartureRevokesSharedWriteBeforeBodyBinding()throws Exception{kb("other",8);share("editor","editor");role("contributor");jdbc.update("DELETE FROM organization_tenant_members WHERE tenant_id=8");mvc.perform(put("/api/v1/knowledge-bases/kb").header("Authorization","Bearer "+owner).contentType("application/json").content("{")).andExpect(status().isForbidden());assertEquals("KB",jdbc.queryForObject("SELECT name FROM knowledge_bases",String.class));}
    @Test void creatorLookupFailureKeepsSimple503BeforeBodyBinding()throws Exception{role("viewer");jdbc.execute("ALTER TABLE knowledge_bases RENAME TO isolated_missing_kbs");try{mvc.perform(put("/api/v1/knowledge-bases/kb").header("Authorization","Bearer "+owner).contentType("application/json").content("{")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.error").value("Service Unavailable: cannot verify resource ownership"));}finally{jdbc.execute("ALTER TABLE isolated_missing_kbs RENAME TO knowledge_bases");}}
    @Test void adminLookupFailureKeepsApplication503BeforeBodyBinding()throws Exception{jdbc.execute("ALTER TABLE knowledge_bases RENAME TO isolated_missing_kbs");try{mvc.perform(put("/api/v1/knowledge-bases/kb").header("Authorization","Bearer "+owner).contentType("application/json").content("{")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.error.message").value("cannot verify KB access right now")).andExpect(jsonPath("$.error.code").value(1008));}finally{jdbc.execute("ALTER TABLE isolated_missing_kbs RENAME TO knowledge_bases");}}
    private void role(String role){jdbc.update("UPDATE tenant_members SET role=? WHERE user_id='owner'",role);}
    private void kb(String creator,long tenant){jdbc.update("INSERT INTO knowledge_bases(id,name,tenant_id,creator_id,embedding_model_id,summary_model_id) VALUES('kb','KB',?,?,'','')",tenant,creator);}
    private void share(String grant,String member){jdbc.update("INSERT INTO organizations(id,name,owner_tenant_id,owner_id) VALUES('org','Org',8,'other')");jdbc.update("INSERT INTO organization_tenant_members(id,organization_id,tenant_id,role) VALUES('source','org',8,'admin'),('target','org',7,?)",member);jdbc.update("INSERT INTO kb_shares(id,knowledge_base_id,organization_id,source_tenant_id,permission,shared_by_user_id) VALUES('share','kb','org',8,?,'other')",grant);}
    private String token(String user,long tenant){String value=jwt.sign(Map.of("user_id",user,"email",user+"@example.com","tenant_id",tenant,"type","access","exp",Instant.now().plusSeconds(3600).getEpochSecond()));repository.storeToken(user,value,"access_token",Instant.now().plusSeconds(3600));return value;}
}
